            d = { de = { "Gewährt dem Paladin eine Chance, zusätzlichen Heiligschaden in Höhe von 70% des normalen Waffenschadens zu verursachen. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.  Hält 30 Sek. lang an.<br /><br />Die Entfesselung der Energie dieses Siegels richtet einen Gegner und fügt ihm sofort <!--ppl20:28:97:560-->69 bis 73 Heiligschaden zu. Wird auf <!--ppl20:28:97:560-->138 bis 146 erhöht, wenn das Ziel betäubt oder handlungsunfähig ist." }, en = { "Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage.  Only one Seal can be active on the Paladin at any one time.  Lasts 30 sec.<br /><br />Unleashing this Seal's energy will judge an enemy, instantly causing <!--ppl20:28:97:560-->69 to 73 Holy damage, <!--ppl20:28:97:560-->138 to 146 if the target is stunned or incapacitated." } } },
          { id = 296, r = 2, c = 3, mr = 2, rp = 10, sid = 26022, node = 105699, entry = 130428, i = "spell_holy_persuitofjustice", st = "changed",
            n = { de = "Streben nach Gerechtigkeit", en = "Pursuit of Justice" },
            d = { de = { "Erhöht normale Bewegungsgeschwindigkeit und Bewegungsgeschwindigkeit beim Reiten um 8%. Ergänzt sich nicht mit anderen Effekten, die die Bewegungsgeschwindigkeit erhöhen.","Erhöht normale Bewegungsgeschwindigkeit und Bewegungsgeschwindigkeit beim Reiten um 15%. Ergänzt sich nicht mit anderen Effekten, die die Bewegungsgeschwindigkeit erhöhen." }, en = { "Increases movement speed and mounted movement speed by 8%.  This does not stack with other movement speed increasing effects.","Increases movement speed and mounted movement speed by 15%.  This does not stack with other movement speed increasing effects." } } },
          { id = 295, r = 3, c = 0, mr = 2, rp = 15, sid = 9799, node = 105698, entry = 130427, i = "spell_holy_eyeforaneye", st = "changed",
            n = { de = "Auge um Auge", en = "Eye for an Eye" },
            d = { de = { "Alle kritischen Treffer gegen Euch lassen den Angreifer 5% des erlittenen Schaden selbst erleiden. Der durch 'Auge um Auge' verursachte Schaden kann 50% der gesamten Gesundheit des Paladins nicht überschreiten.","Alle kritischen Treffer gegen Euch lassen den Angreifer 10% des erlittenen Schaden selbst erleiden. Der durch 'Auge um Auge' verursachte Schaden kann 50% der gesamten Gesundheit des Paladins nicht überschreiten." }, en = { "All critical strikes against you cause 5% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health.","All critical strikes against you cause 10% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health." } } },
