          { id = 291, r = 4, c = 1, mr = 3, rp = 20, sid = 20049, node = 105693, entry = 130422, i = "ability_racial_avatar", st = "changed",
            n = { de = "Rache", en = "Vengeance" },
            rq = { {id=298,q=3} },
            d = { de = { "Erhöht den von Euch verursachten körperlichen und Heiligschaden 30 Sek. lang um 1%, nachdem Ihr einen kritischen Treffer erzielt, der nicht von einem regelmäßigen Schadenseffekt kommt. Bis zu 3-mal stapelbar.","Erhöht den von Euch verursachten körperlichen und Heiligschaden 30 Sek. lang um 2%, nachdem Ihr einen kritischen Treffer erzielt, der nicht von einem regelmäßigen Schadenseffekt kommt. Bis zu 3-mal stapelbar.","Erhöht den von Euch verursachten körperlichen und Heiligschaden 30 Sek. lang um 3%, nachdem Ihr einen kritischen Treffer erzielt, der nicht von einem regelmäßigen Schadenseffekt kommt. Bis zu 3-mal stapelbar." }, en = { "Increases your Physical and Holy damage dealt by 1% for 30 sec after landing a non-periodic critical strike.  Stacks up to 3 times.","Increases your Physical and Holy damage dealt by 2% for 30 sec after landing a non-periodic critical strike.  Stacks up to 3 times.","Increases your Physical and Holy damage dealt by 3% for 30 sec after landing a non-periodic critical strike.  Stacks up to 3 times." } } },
          { id = 292, r = 4, c = 2, mr = 1, rp = 20, sid = 20066, node = 105694, entry = 130423, i = "spell_holy_prayerofhealing", st = "moved",
            n = { de = "Buße", en = "Repentance" },
            d = { de = { "Zwingt den Gegner, zu meditieren, was ihn für 6 Sek. handlungsunfähig macht. Jeglicher verursachte Schaden lässt das Ziel aufwachen. Wirkt nur gegen Humanoide." }, en = { "Puts the enemy target in a state of meditation, incapacitating them for up to 6 sec. Any damage caused will awaken the target. Only works against Humanoids." } } },
          { id = 313, r = 5, c = 1, mr = 3, rp = 25, sid = 1311084, node = 110882, entry = 137880, i = "ability_paladin_enlightenedjudgements", st = "new",
            n = { de = "Champion des Lichts", en = "Champion of the Light" },
            d = { de = { "Erhöht Euren Zauberschaden um bis zu 20% Eurer Intelligenz.","Erhöht Euren Zauberschaden um bis zu 40% Eurer Intelligenz.","Erhöht Euren Zauberschaden um bis zu 60% Eurer Intelligenz." }, en = { "Increases your spell damage by up to 20% of your Intellect.","Increases your spell damage by up to 40% of your Intellect.","Increases your spell damage by up to 60% of your Intellect." } } },
          { id = 312, r = 5, c = 2, mr = 2, rp = 25, sid = 1311085, node = 110880, entry = 137878, i = "spell_holy_divinepurpose", st = "new",
            n = { de = "Rechtsvollstrecker", en = "Instrument of Law" },
            d = { de = { "Verringert die Zauberzeit von 'Hammer des Zorns' um 0.5 Sek. und verringert sämtliche von Euch erzeugte Bedrohung um 10%, während 'Zorn der Gerechtigkeit' nicht aktiv ist.","Verringert die Zauberzeit von 'Hammer des Zorns' um 1.0 Sek. und verringert sämtliche von Euch erzeugte Bedrohung um 20%, während 'Zorn der Gerechtigkeit' nicht aktiv ist." }, en = { "Reduces the cast time of your Hammer of Wrath by 0.5 sec, and reduces all threat you generate by 10% while Righteous Fury is not active.","Reduces the cast time of your Hammer of Wrath by 1.0 sec, and reduces all threat you generate by 20% while Righteous Fury is not active." } } },
          { id = 290, r = 6, c = 1, mr = 1, rp = 30, sid = 1310735, node = 105692, entry = 130421, i = "spell_holy_blessedresillience", st = "new",
            n = { de = "Wendung des Lichts", en = "Twist of Light" },
            d = { de = { "Verringert die Manakosten Eurer Siegelzauber um 20%. Wenn Ihr 'Siegel des Befehls', 'Siegel der Rechtschaffenheit', 'Siegel des Furors' oder 'Siegel der Gerechtigkeit' durch ein anderes Siegel ersetzt, erhaltet Ihr ein Echo dieses Siegels. Euer nächster Nahkampfangriff wendet die Effekte des ersetzten Siegels an und verbraucht das Echo." }, en = { "Reduces the Mana cost of your Seal spells by 20%, and when you replace your Seal of Command, Seal of Righteousness, Seal of Fury, or Seal of Justice with a different Seal, you gain an Echo of that Seal. Your next melee attack applies the replaced Seal's effects, consuming the Echo." } } },
