            n = { de = "Gebet der Besserung", en = "Prayer of Mending" },
            rq = { {id=350,q=1} },
            d = { de = { "Belegt das Ziel mit einem Zauber, der es um [(172 + (Heilung * <!--bc-->0.42899999<!--bc-->)) * (<!--sp1225132:0-->1<!--sp1225132--> * <!--sp14898:0-->1<!--sp14898-->)] Gesundheit heilt, wenn es das nächste Mal Schaden erleidet oder nicht regelmäßige Heilung erhält. Wird die Heilung ausgelöst, springt 'Gebet der Besserung' zu einem Gruppen- oder Schlachtzugsmitglied innerhalb von 20 Metern über. Springt bis zu 5-mal und hält nach jedem Sprung 30 Sek. lang an. Dieser Zauber kann pro Zauberndem nur auf einem Ziel gleichzeitig platziert werden." }, en = { "Places a spell on the target that heals them for [(172 + (Healing * <!--bc-->0.42899999<!--bc-->)) * (<!--sp1225132:0-->1<!--sp1225132--> * <!--sp14898:0-->1<!--sp14898-->)] the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within 20 yards. Jumps up to 5 times and lasts 30 sec after each jump. This spell can only be placed on one target at a time per caster." } } },
