          { id = 388, r = 3, c = 2, mr = 1, rp = 15, sid = 17364, node = 104743, entry = 129403, i = "ability_shaman_stormstrike", st = "changed",
            n = { de = "Sturmschlag", en = "Stormstrike" },
            d = { de = { "Schlagt sofort zu, verursacht normalen Waffenschaden und erhöht den Schaden, den Ihr dem Ziel mit Eurem nächsten Einsatz von 'Blitzschlag', 'Kettenblitzschlag' oder 'Erdschock' zufügt, für 12 Sek. um 20%." }, en = { "Instantly strike for normal weapon damage and increase the damage you deal to the target with your next Lightning Bolt, Chain Lightning, or Earth Shock spell by 20% for 12 sec." } } },
