            n = { de = "Waffen der Geister", en = "Spirit Weapons" },
            d = { de = { "Gewährt Euch eine Chance, gegnerische Nahkampfangriffe zu parieren. Verringert außerdem jegliche erzeugte Bedrohung Eurer Angriffe um 30%, während 'Waffe des Felsbeißers' nicht aktiv ist, und erhöht jegliche erzeugte Bedrohung um 30%, während 'Waffe des Felsbeißers' aktiv ist." }, en = { "Gives a chance to parry enemy melee attacks, reduces all threat generated by your attacks by 30% while Rockbiter Weapon is not active, and increases all threat generated by 30% while Rockbiter Weapon is active." } } },
