          { id = 387, r = 4, c = 2, mr = 2, rp = 20, sid = 1223031, node = 104742, entry = 129402, i = "spell_shaman_improvedstormstrike", st = "new",
            n = { de = "Verbesserter Sturmschlag", en = "Improved Stormstrike" },
            rq = { {id=388,q=1} },
            d = { de = { "Beim Einsatz von 'Sturmschlag' habt Ihr eine Chance von 50%, 15 Sek. lang beim Wirken von Zaubern 50% Manaregeneration zu erhalten. Zudem besteht eine Chance von 50%, die Abklingzeit von 'Sturmschlag' zurückzusetzen, wenn Ihr ausweicht oder pariert.","Beim Einsatz von 'Sturmschlag' habt Ihr eine Chance von 100%, 15 Sek. lang beim Wirken von Zaubern 50% Manaregeneration zu erhalten. Zudem besteht eine Chance von 100%, die Abklingzeit von 'Sturmschlag' zurückzusetzen, wenn Ihr ausweicht oder pariert." }, en = { "When you Stormstrike, you have a 50% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 50% chance to reset each time you Dodge or Parry.","When you Stormstrike, you have a 100% chance to gain 50% mana regeneration while casting spells for 15 sec, and Stormstrike's cooldown has a 100% chance to reset each time you Dodge or Parry." } } },
          { id = 386, r = 5, c = 2, mr = 5, rp = 25, sid = 408498, node = 104741, entry = 129401, i = "spell_shaman_maelstromweapon", st = "new",
            n = { de = "Waffe des Mahlstroms", en = "Maelstrom Weapon" },
