          { id = 382, r = 1, c = 3, mr = 2, rp = 5, sid = 16184, node = 104737, entry = 129397, i = "spell_nature_reincarnation", st = "changed",
            n = { de = "Verbesserte Reinkarnation", en = "Improved Reincarnation" },
            d = { de = { "Verringert die Abklingzeit Eures Zaubers 'Reinkarnation' um 10 Min., erhöht Eure maximale Gesundheit um 2% und erhöht die Menge Gesundheit und Mana, mit der Ihr reinkarniert, um zusätzliche 10%.","Verringert die Abklingzeit Eures Zaubers 'Reinkarnation' um 20 Min., erhöht Eure maximale Gesundheit um 4% und erhöht die Menge Gesundheit und Mana, mit der Ihr reinkarniert, um zusätzliche 20%." }, en = { "Reduces the cooldown of your Reincarnation spell by 10 min, increases your maximum health by 2%, and increases the amount of health and Mana you reincarnate with by an additional 10%.","Reduces the cooldown of your Reincarnation spell by 20 min, increases your maximum health by 4%, and increases the amount of health and Mana you reincarnate with by an additional 20%." } } },
          { id = 376, r = 2, c = 0, mr = 3, rp = 10, sid = 16176, node = 104731, entry = 129391, i = "spell_nature_undyingstrength", st = "changed",
