            d = { de = { "Erhöht den Rüstungswert des Ziels 15 Sek. lang um 8%, nachdem es durch einen Eurer Heilzauber einen kritischen Effekt erhalten hat.","Erhöht den Rüstungswert des Ziels 15 Sek. lang um 17%, nachdem es durch einen Eurer Heilzauber einen kritischen Effekt erhalten hat.","Erhöht den Rüstungswert des Ziels 15 Sek. lang um 25%, nachdem es durch einen Eurer Heilzauber einen kritischen Effekt erhalten hat." }, en = { "Increases your target's armor value by 8% for 15 sec after getting a critical effect from one of your healing spells.","Increases your target's armor value by 17% for 15 sec after getting a critical effect from one of your healing spells.","Increases your target's armor value by 25% for 15 sec after getting a critical effect from one of your healing spells." } } },
