            n = { de = "Heilfokus", en = "Healing Focus" },
            d = { de = { "Verleiht Euch eine Chance von 23%, durch Schaden verursachte Unterbrechungen beim Wirken jeglicher Heilzauber zu vermeiden.","Verleiht Euch eine Chance von 47%, durch Schaden verursachte Unterbrechungen beim Wirken jeglicher Heilzauber zu vermeiden.","Verleiht Euch eine Chance von 70%, durch Schaden verursachte Unterbrechungen beim Wirken jeglicher Heilzauber zu vermeiden." }, en = { "Gives you a 23% chance to avoid interruption caused by damage while casting any healing spell.","Gives you a 47% chance to avoid interruption caused by damage while casting any healing spell.","Gives you a 70% chance to avoid interruption caused by damage while casting any healing spell." } } },
          { id = 377, r = 2, c = 2, mr = 1, rp = 10, sid = 408510, node = 104732, entry = 129392, i = "ability_shaman_watershield", st = "new",
            n = { de = "Wasserschild", en = "Water Shield" },
            d = { de = { "Der Zaubernde wird von 3 Wasserkugeln umgeben. Wenn der Zaubernde durch einen Nahkampf-, Distanz- oder Zauberangriff getroffen wird oder ein Heilzauber des Zaubernden ein kritisches Ergebnis erzielt, werden bei ihm 2% des maximalen Manas wiederhergestellt. Dies verbraucht eine Wasserkugel. Es wird jeweils nur eine Wasserkugel alle paar Sekunden aktiviert. Hält 10 Min. lang an.<br /><br />Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein." }, en = { "The caster is surrounded by 3 globes of water. When a spell, melee, or ranged attack hits the caster or when one of the caster's healing spells gets a critical result, 2% of maximum mana is restored to the caster, expending one water globe. Only one globe will activate every few seconds.  Lasts 10 min.<br /><br />Only one Elemental Shield can be active on the Shaman at any one time." } } },
