            n = { de = "Dämonisches Wissen", en = "Demonic Knowledge" },
            d = { de = { "Erhöht Euren Zauberschaden und den Zauberschaden Eures dämonischen Dieners um einen Betrag, der bis zu 33% Eurer Stufe entspricht, während ein beschworener Dämon aktiv ist.","Erhöht Euren Zauberschaden und den Zauberschaden Eures dämonischen Dieners um einen Betrag, der bis zu 67% Eurer Stufe entspricht, während ein beschworener Dämon aktiv ist.","Erhöht Euren Zauberschaden und den Zauberschaden Eures dämonischen Dieners um einen Betrag, der bis zu 100% Eurer Stufe entspricht, während ein beschworener Dämon aktiv ist." }, en = { "Increases your spell damage and your Demon pet's spell damage by up to 33% of your level while you have a summoned Demon pet active.","Increases your spell damage and your Demon pet's spell damage by up to 67% of your level while you have a summoned Demon pet active.","Increases your spell damage and your Demon pet's spell damage by up to 100% of your level while you have a summoned Demon pet active." } } },
