            n = { de = "Schattenbrand", en = "Shadowburn" },
            d = { de = { "Überzieht das Ziel sofort mit <!--ppl20:24:66:90-->65 bis 74 Schattenschaden. Wenn ein nicht triviales Ziel innerhalb von 8 Sek. nach einem Treffer mit 'Schattenbrand' stirbt, erhält der Zaubernde einen Seelensplitter." }, en = { "Instantly blasts the target for <!--ppl20:24:66:90-->65 to 74 Shadow damage.  If a non-trivial target dies within 8 sec of being hit with Shadowburn, the caster gains a Soul Shard." } } },
