            n = { de = "Feuersbrunst", en = "Conflagrate" },
            d = { de = { "Entzündet ein Ziel, das bereits mit Eurem 'Feuerbrand' belegt ist, fügt ihm <!--ppl25:30:95:90-->88 bis 111 Feuerschaden zu und verbraucht Euren Effekt 'Feuerbrand'." }, en = { "Ignites a target that is already afflicted by your Immolate spell, dealing <!--ppl25:30:95:90-->88 to 111 Fire damage and consuming your Immolate effect." } } },
          { id = 56, r = 4, c = 0, mr = 2, rp = 20, sid = 18073, node = 105878, entry = 130608, i = "spell_fire_volcano", st = "changed",
            n = { de = "Feuerschwall", en = "Pyroclasm" },
            rq = { {id=60,q=3} },
            d = { de = { "Gewährt Eurem Zauber 'Seelenfeuer' eine Chance von 13%, das Ziel für 3 Sek. zu betäuben und Euren Zaubern 'Feuerregen' und 'Höllenfeuer' während ihrer Dauer eine Chance von 13%, getroffene Ziele für 3 Sek. zu betäuben.","Gewährt Eurem Zauber 'Seelenfeuer' eine Chance von 26%, das Ziel für 3 Sek. zu betäuben und Euren Zaubern 'Feuerregen' und 'Höllenfeuer' während ihrer Dauer eine Chance von 26%, getroffene Ziele für 3 Sek. zu betäuben." }, en = { "Gives your Soul Fire spell a 13% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 13% chance over their duration to Stun targets they damage for 3 sec.","Gives your Soul Fire spell a 26% chance to Stun the target for 3 sec, and your Rain of Fire and Hellfire spells a 26% chance over their duration to Stun targets they damage for 3 sec." } } },
          { id = 54, r = 4, c = 1, mr = 1, rp = 20, sid = 1225228, node = 105876, entry = 130606, i = "ability_warlock_baneofhavoc", st = "new",
            n = { de = "Omen der Verwüstung", en = "Bane of Havoc" },
            d = { de = { "Belegt das Ziel 5 Min. lang mit einem Fluch und bewirkt, dass 15% jegliches an anderen Zielen verursachten Schadens des Hexenmeisters ebenfalls dem verfluchten Ziel zugefügt wird. 'Fluch der Verwüstung' ist auf ein Ziel begrenzt und es kann immer nur jeweils ein Omen pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }, en = { "Afflicts the target for 5 min, causing 15% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target." } } },
          { id = 55, r = 4, c = 2, mr = 3, rp = 20, sid = 412751, node = 105877, entry = 130607, i = "spell_fire_meteorstorm", st = "new",
            n = { de = "Feuer und Schwefel", en = "Fire and Brimstone" },
