            n = { de = "Schatten und Flamme", en = "Shadow and Flame" },
            d = { de = { "Wenn Ihr einen Gegner mit 'Feuersbrunst' trefft, erhöht sich Euer verursachter Schattenschaden 20 Sek. lang um 2%, und wenn Ihr einen Gegner mit 'Schattenbrand' trefft, erhöht sich Euer verursachter Feuerschaden 20 Sek. lang um 2%. Darüber hinaus hat 'Feuersbrunst' eine Chance von 20%, 'Feuerbrand' nicht zu verbrauchen, und 'Schattenbrand hat eine Chance von 20%, sofort einen Seelensplitter wiederherzustellen.","Wenn Ihr einen Gegner mit 'Feuersbrunst' trefft, erhöht sich Euer verursachter Schattenschaden 20 Sek. lang um 4%, und wenn Ihr einen Gegner mit 'Schattenbrand' trefft, erhöht sich Euer verursachter Feuerschaden 20 Sek. lang um 4%. Darüber hinaus hat 'Feuersbrunst' eine Chance von 40%, 'Feuerbrand' nicht zu verbrauchen, und 'Schattenbrand hat eine Chance von 40%, sofort einen Seelensplitter wiederherzustellen.","Wenn Ihr einen Gegner mit 'Feuersbrunst' trefft, erhöht sich Euer verursachter Schattenschaden 20 Sek. lang um 6%, und wenn Ihr einen Gegner mit 'Schattenbrand' trefft, erhöht sich Euer verursachter Feuerschaden 20 Sek. lang um 6%. Darüber hinaus hat 'Feuersbrunst' eine Chance von 60%, 'Feuerbrand' nicht zu verbrauchen, und 'Schattenbrand hat eine Chance von 60%, sofort einen Seelensplitter wiederherzustellen.","Wenn Ihr einen Gegner mit 'Feuersbrunst' trefft, erhöht sich Euer verursachter Schattenschaden 20 Sek. lang um 8%, und wenn Ihr einen Gegner mit 'Schattenbrand' trefft, erhöht sich Euer verursachter Feuerschaden 20 Sek. lang um 8%. Darüber hinaus hat 'Feuersbrunst' eine Chance von 80%, 'Feuerbrand' nicht zu verbrauchen, und 'Schattenbrand hat eine Chance von 80%, sofort einen Seelensplitter wiederherzustellen.","Wenn Ihr einen Gegner mit 'Feuersbrunst' trefft, erhöht sich Euer verursachter Schattenschaden 20 Sek. lang um 10%, und wenn Ihr einen Gegner mit 'Schattenbrand' trefft, erhöht sich Euer verursachter Feuerschaden 20 Sek. lang um 10%. Darüber hinaus hat 'Feuersbrunst' eine Chance von 100%, 'Feuerbrand' nicht zu verbrauchen, und 'Schattenbrand hat eine Chance von 100%, sofort einen Seelensplitter wiederherzustellen." }, en = { "Hitting an enemy with Conflagrate increases all Shadow damage you deal by 2% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 2% for 20 sec. In addition, Conflagrate has a 20% chance not to consume Immolate, and Shadowburn has a 20% chance to instantly refund a Soul Shard.","Hitting an enemy with Conflagrate increases all Shadow damage you deal by 4% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 4% for 20 sec. In addition, Conflagrate has a 40% chance not to consume Immolate, and Shadowburn has a 40% chance to instantly refund a Soul Shard.","Hitting an enemy with Conflagrate increases all Shadow damage you deal by 6% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 6% for 20 sec. In addition, Conflagrate has a 60% chance not to consume Immolate, and Shadowburn has a 60% chance to instantly refund a Soul Shard.","Hitting an enemy with Conflagrate increases all Shadow damage you deal by 8% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 8% for 20 sec. In addition, Conflagrate has a 80% chance not to consume Immolate, and Shadowburn has a 80% chance to instantly refund a Soul Shard.","Hitting an enemy with Conflagrate increases all Shadow damage you deal by 10% for 20 sec, and hitting an enemy with Shadowburn increases all Fire damage you deal by 10% for 20 sec. In addition, Conflagrate has a 100% chance not to consume Immolate, and Shadowburn has a 100% chance to instantly refund a Soul Shard." } } },
